package com.game_manager.gm.machine;
import static org.assertj.core.api.Assertions.assertThat;import java.security.*;import java.util.Base64;import org.junit.jupiter.api.Test;
class StationPolicySignerTest {@Test void signsCanonicalPayloadWithConfiguredEd25519Key()throws Exception{KeyPair pair=KeyPairGenerator.getInstance("Ed25519").generateKeyPair();StationPolicySigner signer=new StationPolicySigner(Base64.getEncoder().encodeToString(pair.getPrivate().getEncoded()),"key-1");byte[] payload="{\"configurationVersion\":7}".getBytes(java.nio.charset.StandardCharsets.UTF_8);Signature verifier=Signature.getInstance("Ed25519");verifier.initVerify(pair.getPublic());verifier.update(payload);assertThat(verifier.verify(Base64.getUrlDecoder().decode(signer.sign(payload)))).isTrue();assertThat(signer.keyId()).isEqualTo("key-1");}}
